        return min(tuple(sorted(v)) for v in variants(comp))

    objects = components({(r, c) for r in range(h) for c in range(w)
                          if grid[r][c] not in (bg, frame)})
    by_shape = {}
    all_objects = []
    for obj in objects:
        r, c = next(iter(obj))
        color = grid[r][c]
        by_shape.setdefault(shape_key(obj), Counter())[color] += 1
        all_objects.append((obj, color))

    holes = components({(r, c) for r in range(r0, r1 + 1)
                        for c in range(c0, c1 + 1) if grid[r][c] == bg})
    for hole in holes:
        counts = by_shape.get(shape_key(hole))
        if counts:
            most = max(counts.values())
            color = max(col for col, n in counts.items() if n == most)
        else:
            # A stencil stroke may be elongated. Compare its outline after
            # independently normalizing its height and width.
            best = None
            hh = max(r for r, c in hole) - min(r for r, c in hole) + 1
            hw = max(c for r, c in hole) - min(c for r, c in hole) + 1
            for obj, col in all_objects:
                for v in variants(obj):
                    oh = max(r for r, c in v) + 1
                    ow = max(c for r, c in v) + 1
                    score = abs(hh - oh) + abs(hw - ow)
                    if oh == hh:
                        # Reward matching rows when horizontal arms stretch.
                        a = Counter(r for r, c in hole)
                        b = Counter(r for r, c in v)
                        score -= sum(min(a[r], b[r]) for r in a) * 0.01
                    if best is None or score < best[0]:
                        best = (score, col)
            color = best[1] if best else frame
        for r, c in hole:
            out[r - r0][c - c0] = color
    return out
